export function mixWithWhite(hex, amount) {
  const n = parseInt(hex.slice(1), 16);
  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  const mix = (c) => Math.round(c + (255 - c) * amount);
  return `rgb(${mix(r)}, ${mix(g)}, ${mix(b)})`;
}

export function drawCover(ctx, img, dx, dy, dW, dH, focusX = 0.5, focusY = 0.5) {
  const imgRatio = img.width / img.height;
  const boxRatio = dW / dH;
  let sx, sy, sw, sh;
  if (imgRatio > boxRatio) {
    sh = img.height; sw = sh * boxRatio; sy = 0; sx = (img.width - sw) * focusX;
  } else {
    sw = img.width; sh = sw / boxRatio; sx = 0; sy = (img.height - sh) * focusY;
  }
  ctx.drawImage(img, sx, sy, sw, sh, dx, dy, dW, dH);
}

export function wrapText(ctx, text, maxWidth) {
  const words = text.split(" ");
  const lines = [];
  let line = "";
  for (const word of words) {
    const test = line ? line + " " + word : word;
    if (ctx.measureText(test).width > maxWidth && line) { lines.push(line); line = word; }
    else line = test;
  }
  if (line) lines.push(line);
  return lines;
}

export function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

export function archedRect(ctx, x, y, w, h) {
  const r = Math.min(w / 2, h * 0.55);
  ctx.beginPath();
  ctx.moveTo(x, y + h);
  ctx.lineTo(x, y + r);
  ctx.arcTo(x, y, x + r, y, r);
  ctx.lineTo(x + w - r, y);
  ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.lineTo(x + w, y + h);
  ctx.closePath();
}

export function useUploadedImage() {
  const [img, setImg] = useState(null);
  const [name, setName] = useState("");
  const load = (file) => {
    if (!file || !file.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const image = new Image();
      image.onload = () => setImg(image);
      image.src = e.target.result;
    };
    setName(file.name);
    reader.readAsDataURL(file);
  };
  const clear = () => { setImg(null); setName(""); };
  return { img, name, load, clear };
}

// Loads a default hosted image (e.g. her standing headshot/logo) but still lets her
// swap in a different file any time — upload always takes priority over the default.
export function useAgentAsset(defaultUrl, defaultLabel) {
  const [img, setImg] = useState(null);
  const [source, setSource] = useState("loading"); // loading | default | custom | error
  const [name, setName] = useState(defaultLabel);

  useEffect(() => {
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.onload = () => { setImg(image); setSource("default"); };
    image.onerror = () => setSource("error");
    image.src = defaultUrl;
  }, [defaultUrl]);

  const load = (file) => {
    if (!file || !file.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const image = new Image();
      image.onload = () => setImg(image);
      image.src = e.target.result;
    };
    setName(file.name);
    setSource("custom");
    reader.readAsDataURL(file);
  };

  const clear = () => {
    setName(defaultLabel);
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.onload = () => { setImg(image); setSource("default"); };
    image.onerror = () => setSource("error");
    image.src = defaultUrl;
  };

  return { img, name, source, load, clear };
}

export function UploadBox({ label, icon: Icon, state, hint }) {
  const inputRef = useRef(null);
  const [dragOver, setDragOver] = useState(false);
  const isDefault = state.source === "default";
  return (
    <div>
      <span className="font-mono text-xs block mb-1.5" style={{ color: UI.inkSoft, letterSpacing: "0.04em" }}>{label}</span>
      <div
        onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
        onDragLeave={() => setDragOver(false)}
        onDrop={(e) => { e.preventDefault(); setDragOver(false); state.load(e.dataTransfer.files[0]); }}
        onClick={() => inputRef.current?.click()}
        className="rounded border-2 border-dashed flex items-center gap-2 cursor-pointer transition"
        style={{ borderColor: dragOver ? PINK : UI.line, background: UI.card, padding: "0.7rem 0.9rem" }}
      >
        <Icon size={16} style={{ color: PINK, flexShrink: 0 }} />
        {state.name ? (
          <div className="flex items-center gap-2 font-body text-sm flex-1 min-w-0">
            <span className="truncate">{isDefault ? `${state.name} (default)` : state.name}</span>
            {!isDefault && state.source !== "loading" && (
              <button onClick={(e) => { e.stopPropagation(); state.clear(); }} style={{ color: UI.inkSoft, flexShrink: 0 }} title="Reset to default">
                <X size={13} />
              </button>
            )}
          </div>
        ) : (
          <span className="font-body text-xs" style={{ color: UI.inkSoft }}>{hint}</span>
        )}
        <input ref={inputRef} type="file" accept="image/*" className="hidden" onChange={(e) => state.load(e.target.files[0])} />
      </div>
      {state.source === "error" && (
        <p className="font-body text-xs mt-1" style={{ color: PINK }}>
          Couldn't load the default image — upload one here instead.
        </p>
      )}
    </div>
  );
}


